1	import { useEffect, useState, type FormEvent } from 'react';
2	import { ClientStatement } from './ClientStatement';
3	import { formatMoney } from '../../ui/money';
4	
5	// Opened from the clients list: a client's detail view lists the projects done for them, scoped to
6	// the client via /api/clients/<id>/projects. Reuses the project-row-<id>/project-name anchors so the
7	// listing reads the same way wherever projects appear. It also keeps the client's contacts (name,
8	// email, role), scoped the same way via /api/clients/<id>/contacts, with a form to add one.
9	type Project = { id: number; name: string };
10	type Contact = { id: number; name: string; email: string; role: string; primary: boolean };
11	type Counts = { projects: number; contacts: number };
12	// An open invoice the client still owes on — a candidate to put part of a lump payment against.
13	type OpenInvoice = { id: number; projectName: string; amount: number; due: number };
14	
15	// A contact must carry a proper email address too, same guard as clients: a single non-whitespace
16	// local part, an @, and a dotted domain.
17	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
18	
19	export function ClientDetail({ clientId }: { clientId: number }) {
20	  const [projects, setProjects] = useState<Project[]>([]);
21	  const [contacts, setContacts] = useState<Contact[]>([]);
22	  const [counts, setCounts] = useState<Counts>({ projects: 0, contacts: 0 });
23	  const [name, setName] = useState('');
24	  const [email, setEmail] = useState('');
25	  const [role, setRole] = useState('');
26	  const [emailError, setEmailError] = useState(false);
27	  const [statementOpen, setStatementOpen] = useState(false);
28	  // Recording a lump payment split across the client's open invoices: whether the form is open, the
29	  // lump sum, the date it was paid, the open invoices to split across, and each invoice's share.
30	  const [paymentOpen, setPaymentOpen] = useState(false);
31	  const [openInvoices, setOpenInvoices] = useState<OpenInvoice[]>([]);
32	  const [paymentAmount, setPaymentAmount] = useState('');
33	  const [paymentDate, setPaymentDate] = useState('');
34	  const [allocations, setAllocations] = useState<Record<number, string>>({});
35	  // By default a client's page shows only their ACTIVE projects — the work still in play. Flipping
36	  // this reveals the finished and hidden (archived) ones too, by asking the server for them all.
37	  const [showAll, setShowAll] = useState(false);
38	
39	  async function loadContacts() {
40	    const res = await fetch(`/api/clients/${clientId}/contacts`);
41	    if (res.ok) {
42	      setContacts(await res.json());
43	    }
44	  }
45	
46	  // The at-a-glance counts of projects and contacts come from the server, counted in SQL.
47	  async function loadCounts() {
48	    const res = await fetch(`/api/clients/${clientId}/counts`);
49	    if (res.ok) {
50	      setCounts(await res.json());
51	    }
52	  }
53	
54	  useEffect(() => {
55	    async function load() {
56	      const res = await fetch(
57	        `/api/clients/${clientId}/projects${showAll ? '?all=true' : ''}`,
58	      );
59	      if (res.ok) {
60	        setProjects(await res.json());
61	      }
62	    }
63	    void load();
64	  }, [clientId, showAll]);
65	
66	  useEffect(() => {
67	    void loadContacts();
68	    void loadCounts();
69	  }, [clientId]);
70	
71	  // A client has one main contact. Pick it by flagging the chosen contact primary on the server,
72	  // then reload so the "who is primary" line and the row buttons reflect the new choice.
73	  async function onPickPrimary(contactId: number) {
74	    const res = await fetch(
75	      `/api/clients/${clientId}/contacts/${contactId}/primary`,
76	      { method: 'POST' },
77	    );
78	    if (res.ok) {
79	      setContacts(await res.json());
80	    }
81	  }
82	
83	  const primaryContact = contacts.find((contact) => contact.primary);
84	
85	  async function onAddContact(event: FormEvent) {
86	    event.preventDefault();
87	    if (!EMAIL_RE.test(email)) {
88	      setEmailError(true);
89	      return;
90	    }
91	    setEmailError(false);
92	    const res = await fetch(`/api/clients/${clientId}/contacts`, {
93	      method: 'POST',
94	      headers: { 'Content-Type': 'application/json' },
95	      body: JSON.stringify({ name, email, role }),
96	    });
97	    if (res.ok) {
98	      setName('');
99	      setEmail('');
100	      setRole('');
101	      await loadContacts();
102	      await loadCounts();
103	    }
104	  }
105	
106	  // Open the lump-payment form, loading the client's open invoices (those with something still due)
107	  // from their statement so each can be given a share of the payment.
108	  async function onOpenPayment() {
109	    setPaymentOpen(true);
110	    const res = await fetch(`/api/clients/${clientId}/statement`);
111	    if (res.ok) {
112	      const statement = (await res.json()) as { invoices: OpenInvoice[] };
113	      setOpenInvoices(statement.invoices.filter((invoice) => Number(invoice.due) > 0));
114	    }
115	  }
116	
117	  // Split the lump payment across the invoices: send each invoice's share, then close the form.
118	  async function onRecordPayment(event: FormEvent) {
119	    event.preventDefault();
120	    const splits = openInvoices
121	      .map((invoice) => ({ invoiceId: invoice.id, amount: Number(allocations[invoice.id] ?? '') }))
122	      .filter((split) => split.amount > 0);
123	    const res = await fetch(`/api/clients/${clientId}/payments`, {
124	      method: 'POST',
125	      headers: { 'Content-Type': 'application/json' },
126	      body: JSON.stringify({ amount: Number(paymentAmount), date: paymentDate, allocations: splits }),
127	    });
128	    if (res.ok) {
129	      setPaymentOpen(false);
130	      setPaymentAmount('');
131	      setPaymentDate('');
132	      setAllocations({});
133	    }
134	  }
135	
136	  return (
137	    <section data-testid="client-detail">
138	      <dl data-testid="client-counts">
139	        <dt>Jobs</dt>
140	        <dd data-testid="client-projects-count">{counts.projects}</dd>
141	        <dt>Contacts</dt>
142	        <dd data-testid="client-contacts-count">{counts.contacts}</dd>
143	      </dl>
144	
145	      <button
146	        data-testid="client-statement-open"
147	        type="button"
148	        onClick={() => setStatementOpen(true)}
149	      >
150	        Statement
151	      </button>
152	      {statementOpen && <ClientStatement clientId={clientId} />}
153	
154	      <button
155	        data-testid="client-record-payment"
156	        type="button"
157	        onClick={() => void onOpenPayment()}
158	      >
159	        Record payment
160	      </button>
161	      {paymentOpen && (
162	        <form data-testid="payment-form" onSubmit={onRecordPayment}>
163	          <input
164	            data-testid="payment-form-amount"
165	            placeholder="Amount"
166	            value={paymentAmount}
167	            onChange={(e) => setPaymentAmount(e.target.value)}
168	          />
169	          <input
170	            data-testid="payment-form-date"
171	            placeholder="Date"
172	            value={paymentDate}
173	            onChange={(e) => setPaymentDate(e.target.value)}
174	          />
175	          <table data-testid="payment-alloc-table">
176	            <thead>
177	              <tr>
178	                <th>Invoice</th>
179	                <th>Job</th>
180	                <th>Left to pay</th>
181	                <th>Apply</th>
182	              </tr>
183	            </thead>
184	            <tbody>
185	              {openInvoices.map((invoice) => (
186	                <tr key={invoice.id} data-testid={`payment-alloc-row-${invoice.id}`}>
187	                  <td>{invoice.id}</td>
188	                  <td>{invoice.projectName}</td>
189	                  <td>{formatMoney(invoice.due)}</td>
190	                  <td>
191	                    <input
192	                      data-testid={`payment-alloc-${invoice.id}`}
193	                      placeholder="0"
194	                      value={allocations[invoice.id] ?? ''}
195	                      onChange={(e) =>
196	                        setAllocations((prev) => ({ ...prev, [invoice.id]: e.target.value }))
197	                      }
198	                    />
199	                  </td>
200	                </tr>
201	              ))}
202	            </tbody>
203	          </table>
204	          <button data-testid="payment-form-submit" type="submit">
205	            Record payment
206	          </button>
207	        </form>
208	      )}
209	
210	      <h2>Jobs</h2>
211	      <button
212	        data-testid="client-projects-show-all"
213	        type="button"
214	        aria-pressed={showAll}
215	        onClick={() => setShowAll((v) => !v)}
216	      >
217	        {showAll ? 'Show active only' : 'Show finished and hidden'}
218	      </button>
219	      <table data-testid="client-projects-table">
220	        <thead>
221	          <tr>
222	            <th>Name</th>
223	          </tr>
224	        </thead>
225	        <tbody>
226	          {projects.map((project) => (
227	            <tr key={project.id} data-testid={`project-row-${project.id}`}>
228	              <td data-testid="project-name">{project.name}</td>
229	            </tr>
230	          ))}
231	        </tbody>
232	      </table>
233	
234	      <h2>Contacts</h2>
235	      <p>
236	        Main contact:{' '}
237	        <span data-testid="client-primary-contact">{primaryContact?.name ?? ''}</span>
238	      </p>
239	      <table data-testid="client-contacts-table">
240	        <thead>
241	          <tr>
242	            <th>Name</th>
243	            <th>Email</th>
244	            <th>Role</th>
245	            <th>Main</th>
246	          </tr>
247	        </thead>
248	        <tbody>
249	          {contacts.map((contact) => (
