1	package net.officefloor.hq.app;
2	
3	import java.time.LocalDate;
4	import java.time.OffsetDateTime;
5	import java.time.ZoneOffset;
6	import java.util.List;
7	import java.util.Map;
8	import org.springframework.context.annotation.Profile;
9	import org.springframework.jdbc.core.JdbcTemplate;
10	import org.springframework.web.bind.annotation.PostMapping;
11	import org.springframework.web.bind.annotation.RequestBody;
12	import org.springframework.web.bind.annotation.RequestMapping;
13	import org.springframework.web.bind.annotation.RestController;
14	
15	/**
16	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
17	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
18	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
19	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
20	 */
21	@Profile("harness")
22	@RestController
23	@RequestMapping("/__test__")
24	public class TestSupportController {
25	
26	    private final Audit audit;
27	    private final JdbcTemplate jdbc;
28	
29	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
30	        this.audit = audit;
31	        this.jdbc = jdbc;
32	    }
33	
34	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
35	    @PostMapping("/reset")
36	    public void reset() {
37	        audit.clear();
38	        // Disable FK checks so a referenced parent (clients) can be truncated alongside its child.
39	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
40	        jdbc.execute("TRUNCATE TABLE payments RESTART IDENTITY");
41	        jdbc.execute("TRUNCATE TABLE line_items RESTART IDENTITY");
42	        jdbc.execute("TRUNCATE TABLE invoices RESTART IDENTITY");
43	        jdbc.execute("TRUNCATE TABLE contacts RESTART IDENTITY");
44	        jdbc.execute("TRUNCATE TABLE tasks RESTART IDENTITY");
45	        jdbc.execute("TRUNCATE TABLE notes RESTART IDENTITY");
46	        jdbc.execute("TRUNCATE TABLE project_tags RESTART IDENTITY");
47	        jdbc.execute("TRUNCATE TABLE tags RESTART IDENTITY");
48	        jdbc.execute("TRUNCATE TABLE projects RESTART IDENTITY");
49	        jdbc.execute("TRUNCATE TABLE clients RESTART IDENTITY");
50	        jdbc.execute("TRUNCATE TABLE dashboard_settings");
51	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
52	    }
53	
54	    /**
55	     * Parse a note's {@code at} stamp, accepting either a full ISO offset date-time or a plain
56	     * date (treated as the start of that day in UTC), so a fixture can write either form.
57	     */
58	    private static OffsetDateTime parseInstant(String value) {
59	        return value.contains("T")
60	                ? OffsetDateTime.parse(value)
61	                : LocalDate.parse(value).atStartOfDay().atOffset(ZoneOffset.UTC);
62	    }
63	
64	    /** Insert the fixture a spec needs; the payload shape evolves with the schema. */
65	    @PostMapping("/seed")
66	    @SuppressWarnings("unchecked")
67	    public void seed(@RequestBody Map<String, Object> fixture) {
68	        // The dashboard measures invoice "overdue" against a fixed reference date; store it when the
69	        // fixture supplies one so the home-screen count is deterministic.
70	        Object asOf = fixture.get("asOf");
71	        if (asOf != null) {
72	            jdbc.update("INSERT INTO dashboard_settings (id, as_of) VALUES (1, ?)", asOf.toString());
73	        }
74	
75	        List<Map<String, Object>> clients =
76	                (List<Map<String, Object>>) fixture.getOrDefault("clients", List.of());
77	        long maxClientId = 0;
78	        for (Map<String, Object> client : clients) {
79	            long id = ((Number) client.get("id")).longValue();
80	            // Archived clients are tucked away: honour the fixture flag so a spec can seed a client
81	            // that starts off the main list (and can then be restored back onto it).
82	            boolean archived = Boolean.TRUE.equals(client.getOrDefault("archived", Boolean.FALSE));
83	            // Seed with the fixture's explicit id (JdbcTemplate, not JPA) so specs can assert by id.
84	            jdbc.update("INSERT INTO clients (id, name, email, archived) VALUES (?, ?, ?, ?)",
85	                    id, client.get("name"), client.get("email"), archived);
86	            maxClientId = Math.max(maxClientId, id);
87	        }
88	        if (maxClientId > 0) {
89	            // Advance the identity so app-generated ids don't collide with seeded rows.
90	            jdbc.execute("ALTER TABLE clients ALTER COLUMN id RESTART WITH " + (maxClientId + 1));
91	        }
92	
93	        List<Map<String, Object>> projects =
94	                (List<Map<String, Object>>) fixture.getOrDefault("projects", List.of());
95	        long maxProjectId = 0;
96	        for (Map<String, Object> project : projects) {
97	            long id = ((Number) project.get("id")).longValue();
98	            long clientId = ((Number) project.get("clientId")).longValue();
99	            String status = (String) project.getOrDefault("status", "ACTIVE");
100	            boolean archived = Boolean.TRUE.equals(project.getOrDefault("archived", Boolean.FALSE));
101	            double budget = ((Number) project.getOrDefault("budget", 0)).doubleValue();
102	            String code = (String) project.get("code");
103	            jdbc.update(
104	                    "INSERT INTO projects (id, name, client_id, status, archived, budget, code) VALUES (?, ?, ?, ?, ?, ?, ?)",
105	                    id, project.get("name"), clientId, status, archived, budget, code);
106	            maxProjectId = Math.max(maxProjectId, id);
107	        }
108	        if (maxProjectId > 0) {
109	            jdbc.execute("ALTER TABLE projects ALTER COLUMN id RESTART WITH " + (maxProjectId + 1));
110	        }
111	
112	        List<Map<String, Object>> contacts =
113	                (List<Map<String, Object>>) fixture.getOrDefault("contacts", List.of());
114	        long maxContactId = 0;
115	        for (Map<String, Object> contact : contacts) {
116	            long id = ((Number) contact.get("id")).longValue();
117	            long clientId = ((Number) contact.get("clientId")).longValue();
118	            boolean primary = Boolean.TRUE.equals(contact.getOrDefault("primary", Boolean.FALSE));
119	            jdbc.update(
120	                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary) VALUES (?, ?, ?, ?, ?, ?)",
121	                    id, clientId, contact.get("name"), contact.get("email"), contact.get("role"),
122	                    primary);
123	            maxContactId = Math.max(maxContactId, id);
124	        }
125	        if (maxContactId > 0) {
126	            jdbc.execute("ALTER TABLE contacts ALTER COLUMN id RESTART WITH " + (maxContactId + 1));
127	        }
128	
129	        List<Map<String, Object>> tasks =
130	                (List<Map<String, Object>>) fixture.getOrDefault("tasks", List.of());
131	        long maxTaskId = 0;
132	        for (Map<String, Object> task : tasks) {
133	            long id = ((Number) task.get("id")).longValue();
134	            long projectId = ((Number) task.get("projectId")).longValue();
135	            boolean done = Boolean.TRUE.equals(task.getOrDefault("done", Boolean.FALSE));
136	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
137	                    id, projectId, task.get("title"), done);
138	            maxTaskId = Math.max(maxTaskId, id);
139	        }
140	        if (maxTaskId > 0) {
141	            jdbc.execute("ALTER TABLE tasks ALTER COLUMN id RESTART WITH " + (maxTaskId + 1));
142	        }
143	
144	        List<Map<String, Object>> tags =
145	                (List<Map<String, Object>>) fixture.getOrDefault("tags", List.of());
146	        long maxTagId = 0;
147	        for (Map<String, Object> tag : tags) {
148	            long id = ((Number) tag.get("id")).longValue();
149	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id, tag.get("name"));
150	            maxTagId = Math.max(maxTagId, id);
151	        }
152	        if (maxTagId > 0) {
153	            jdbc.execute("ALTER TABLE tags ALTER COLUMN id RESTART WITH " + (maxTagId + 1));
154	        }
155	
156	        List<Map<String, Object>> projectTags =
157	                (List<Map<String, Object>>) fixture.getOrDefault("projectTags", List.of());
158	        for (Map<String, Object> projectTag : projectTags) {
159	            long projectId = ((Number) projectTag.get("projectId")).longValue();
160	            long tagId = ((Number) projectTag.get("tagId")).longValue();
161	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
162	                    projectId, tagId);
163	        }
164	
165	        List<Map<String, Object>> notes =
166	                (List<Map<String, Object>>) fixture.getOrDefault("notes", List.of());
167	        long maxNoteId = 0;
168	        for (Map<String, Object> note : notes) {
169	            long id = ((Number) note.get("id")).longValue();
170	            long targetId = ((Number) note.get("targetId")).longValue();
171	            jdbc.update(
172	                    "INSERT INTO notes (id, target_type, target_id, text, at) VALUES (?, ?, ?, ?, ?)",
173	                    id, note.get("targetType"), targetId, note.get("text"),
174	                    parseInstant((String) note.get("at")));
175	            maxNoteId = Math.max(maxNoteId, id);
176	        }
177	        if (maxNoteId > 0) {
178	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + (maxNoteId + 1));
179	        }
180	
181	        List<Map<String, Object>> invoices =
182	                (List<Map<String, Object>>) fixture.getOrDefault("invoices", List.of());
183	        long maxInvoiceId = 0;
184	        long maxLineItemId = 0;
185	        for (Map<String, Object> invoice : invoices) {
186	            long id = ((Number) invoice.get("id")).longValue();
187	            long projectId = ((Number) invoice.get("projectId")).longValue();
188	            // An invoice is itemised: its amount is derived as the sum of each line's qty * price.
189	            // A fixture may still pass an explicit amount for a line-item-less invoice.
190	            List<Map<String, Object>> lineItems =
191	                    (List<Map<String, Object>>) invoice.getOrDefault("lineItems", List.of());
192	            double amount = lineItems.isEmpty() && invoice.get("amount") != null
193	                    ? ((Number) invoice.get("amount")).doubleValue()
194	                    : 0;
195	            for (Map<String, Object> lineItem : lineItems) {
196	                amount += ((Number) lineItem.get("qty")).doubleValue()
197	                        * ((Number) lineItem.get("unitPrice")).doubleValue();
198	            }
199	            String status = (String) invoice.getOrDefault("status", "UNPAID");
200	            Object issuedDate = invoice.getOrDefault("issuedDate", LocalDate.now().toString());
201	            Object dueDate = invoice.getOrDefault("dueDate", LocalDate.now().toString());
202	            // A percentage discount taken off the subtotal; absent means no discount.
203	            double discountPct = ((Number) invoice.getOrDefault("discountPct", 0)).doubleValue();
204	            // A sales tax percentage applied after the discount; absent means no tax.
205	            double taxPct = ((Number) invoice.getOrDefault("taxPct", 0)).doubleValue();
