1	package net.officefloor.hq.app.clients;
2	
3	import java.math.BigDecimal;
4	import java.util.ArrayList;
5	import java.util.Comparator;
6	import java.util.HashMap;
7	import java.util.LinkedHashMap;
8	import java.util.List;
9	import java.util.Map;
10	import java.util.regex.Pattern;
11	import net.officefloor.hq.app.Audit;
12	import org.springframework.jdbc.core.JdbcTemplate;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	/** Business logic for clients. Each call runs in its own transaction. */
17	@Service
18	public class ClientService {
19	
20	    // A client must carry a proper email address (mirrors the front-end guard).
21	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
22	
23	    private final ClientRepository repository;
24	    private final ContactRepository contacts;
25	    private final JdbcTemplate jdbc;
26	    private final Audit audit;
27	
28	    public ClientService(ClientRepository repository, ContactRepository contacts, JdbcTemplate jdbc,
29	            Audit audit) {
30	        this.repository = repository;
31	        this.contacts = contacts;
32	        this.jdbc = jdbc;
33	        this.audit = audit;
34	    }
35	
36	    /** List the clients still in play. Archived clients are tucked away and omitted. */
37	    @Transactional(readOnly = true)
38	    public List<Client> list() {
39	        return repository.findByArchivedFalseOrderByIdAsc();
40	    }
41	
42	    /**
43	     * Clients whose name contains {@code query} (case-insensitive); all clients when blank. Archived
44	     * clients are tucked away, so they drop off the search too.
45	     */
46	    @Transactional(readOnly = true)
47	    public List<Client> search(String query) {
48	        if (query == null || query.isBlank()) {
49	            return list();
50	        }
51	        return repository.findByArchivedFalseAndNameContainingIgnoreCaseOrderByIdAsc(query.trim());
52	    }
53	
54	    /**
55	     * The visible clients (honouring the name search), each with how much they still owe, ordered the
56	     * way the list asks for: {@code "name"} alphabetically (case-insensitive), {@code "outstanding"}
57	     * by most owed first, anything else by the natural id order. The amount owed is computed the same
58	     * way as a client statement — each invoice's discounted total minus its payments, summed.
59	     */
60	    @Transactional(readOnly = true)
61	    public List<ClientView> listSorted(String query, String sort) {
62	        Map<Long, BigDecimal> owed = outstandingByClient();
63	        List<ClientView> views = new ArrayList<>();
64	        for (Client client : search(query)) {
65	            views.add(new ClientView(client.getId(), client.getName(), client.getEmail(),
66	                    owed.getOrDefault(client.getId(), BigDecimal.ZERO)));
67	        }
68	        if ("name".equals(sort)) {
69	            views.sort(Comparator.comparing(ClientView::getName, String.CASE_INSENSITIVE_ORDER)
70	                    .thenComparing(ClientView::getId));
71	        } else if ("outstanding".equals(sort)) {
72	            views.sort(Comparator.comparing(ClientView::getOutstanding).reversed()
73	                    .thenComparing(ClientView::getId));
74	        }
75	        return views;
76	    }
77	
78	    /** What each client still owes across all their projects' invoices, keyed by client id. */
79	    private Map<Long, BigDecimal> outstandingByClient() {
80	        Map<Long, BigDecimal> owed = new HashMap<>();
81	        jdbc.query(
82	                "SELECT p.client_id AS client_id, "
83	                        + "SUM(i.amount * (1 - i.discount_pct / 100) "
84	                        + "- COALESCE((SELECT SUM(pay.amount) FROM payments pay "
85	                        + "WHERE pay.invoice_id = i.id), 0)) AS owed "
86	                        + "FROM invoices i JOIN projects p ON i.project_id = p.id "
87	                        + "GROUP BY p.client_id",
88	                rs -> {
89	                    BigDecimal value = rs.getBigDecimal("owed");
90	                    owed.put(rs.getLong("client_id"), value == null ? BigDecimal.ZERO : value);
91	                });
92	        return owed;
93	    }
94	
95	    /** The clients tucked away (archived), oldest first — the "show archived" view's contents. */
96	    @Transactional(readOnly = true)
97	    public List<ClientView> listArchived() {
98	        return repository.findByArchivedTrueOrderByIdAsc().stream()
99	                .map(c -> new ClientView(c.getId(), c.getName(), c.getEmail()))
100	                .toList();
101	    }
102	
103	    /**
104	     * Bring an archived client back: clear the flag so they return to the main list and search.
105	     * Records an audit entry so the action can be checked later, and returns the clients that remain
106	     * archived.
107	     */
108	    @Transactional
109	    public List<ClientView> restore(Long id) {
110	        if (id == null) {
111	            throw new IllegalArgumentException("A client id is required to restore");
112	        }
113	        jdbc.update("UPDATE clients SET archived = FALSE WHERE id = ?", id);
114	        audit.record("CLIENT_RESTORED id=" + id);
115	        return listArchived();
116	    }
117	
118	    /**
119	     * Archive a client: keep the row (and everything hanging off it) but flag it so it drops off the
120	     * list and search. Records an audit entry so the action can be checked later, and returns the
121	     * clients that remain visible.
122	     */
123	    @Transactional
124	    public List<Client> archive(Long id) {
125	        if (id == null) {
126	            throw new IllegalArgumentException("A client id is required to archive");
127	        }
128	        jdbc.update("UPDATE clients SET archived = TRUE WHERE id = ?", id);
129	        audit.record("CLIENT_ARCHIVED id=" + id);
130	        return list();
131	    }
132	
133	    /**
134	     * The projects done for a client, oldest first. By default only ACTIVE, non-archived projects —
135	     * the work still in play — are returned; pass {@code includeAll} to also surface the finished and
136	     * archived (hidden) ones (how the client page's "show all" toggle reveals them). Reads the
137	     * {@code projects} table via SQL so the clients feature stays self-contained and does not import
138	     * the projects feature's Java types.
139	     */
140	    @Transactional(readOnly = true)
141	    public List<ClientProjectView> projectsFor(Long clientId, boolean includeAll) {
142	        String filter = includeAll ? "" : " AND status = 'ACTIVE' AND archived = FALSE";
143	        return jdbc.query(
144	                "SELECT id, name FROM projects WHERE client_id = ?" + filter + " ORDER BY id ASC",
145	                (rs, i) -> new ClientProjectView(rs.getLong("id"), rs.getString("name")),
146	                clientId);
147	    }
148	
149	    /**
150	     * At-a-glance counts for a client's page: how many projects and contacts they have. Counts in
151	     * SQL so a large client doesn't have to ship its full project/contact lists just to be tallied.
152	     */
153	    @Transactional(readOnly = true)
154	    public ClientCountsView countsFor(Long clientId) {
155	        Long projects = jdbc.queryForObject(
156	                "SELECT COUNT(*) FROM projects WHERE client_id = ? AND archived = FALSE",
157	                Long.class, clientId);
158	        Long contacts = jdbc.queryForObject(
159	                "SELECT COUNT(*) FROM contacts WHERE client_id = ?", Long.class, clientId);
160	        return new ClientCountsView(projects == null ? 0 : projects, contacts == null ? 0 : contacts);
161	    }
162	
163	    /**
164	     * A statement for a client: every invoice raised across all of the client's projects, gathered
165	     * in one place, each with how much is still due (its amount minus whatever has been paid against
166	     * it). The outstanding total is the sum of those dues — what the client still owes. Read via SQL
167	     * so the clients feature stays self-contained and does not import the invoices feature's types.
168	     */
169	    @Transactional(readOnly = true)
170	    public ClientStatementView statementFor(Long clientId) {
171	        // The amount owed on an invoice is its discounted total — the percentage discount comes off
172	        // the subtotal before anything is owed — so both the per-invoice amount and what is still due
173	        // (that discounted total minus payments) reflect the discount, matching the invoice and
174	        // dashboard views.
175	        List<ClientStatementInvoiceView> invoices = jdbc.query(
176	                "SELECT i.id, p.id AS project_id, p.name AS project_name, "
177	                        + "i.amount * (1 - i.discount_pct / 100) AS net_amount, i.status, "
178	                        + "i.amount * (1 - i.discount_pct / 100) "
179	                        + "- COALESCE((SELECT SUM(pay.amount) FROM payments pay "
180	                        + "WHERE pay.invoice_id = i.id), 0) AS due_amount "
181	                        + "FROM invoices i JOIN projects p ON i.project_id = p.id "
182	                        + "WHERE p.client_id = ? ORDER BY p.id ASC, i.id ASC",
183	                (rs, i) -> new ClientStatementInvoiceView(rs.getLong("id"), rs.getLong("project_id"),
184	                        rs.getString("project_name"), rs.getBigDecimal("net_amount"),
185	                        rs.getString("status"), rs.getBigDecimal("due_amount")),
186	                clientId);
187	        // Group the invoices under the job (project) they were raised against, keeping the ordered
188	        // first-seen project order, so the statement can show each job with a subtotal of what is
189	        // still due on it. The subtotals sum to the outstanding total below.
190	        Map<Long, List<ClientStatementInvoiceView>> byProject = new LinkedHashMap<>();
191	        for (ClientStatementInvoiceView invoice : invoices) {
192	            byProject.computeIfAbsent(invoice.getProjectId(), k -> new ArrayList<>()).add(invoice);
193	        }
194	        List<ClientStatementProjectView> projects = new ArrayList<>();
195	        for (List<ClientStatementInvoiceView> group : byProject.values()) {
196	            BigDecimal subtotal = group.stream().map(ClientStatementInvoiceView::getDue)
197	                    .reduce(BigDecimal.ZERO, BigDecimal::add);
198	            ClientStatementInvoiceView first = group.get(0);
199	            projects.add(new ClientStatementProjectView(first.getProjectId(), first.getProjectName(),
200	                    subtotal, group));
201	        }
202	        BigDecimal outstanding = invoices.stream().map(ClientStatementInvoiceView::getDue)
203	                .reduce(BigDecimal.ZERO, BigDecimal::add);
204	        return new ClientStatementView(invoices, projects, outstanding);
205	    }
206	
207	    /** The contacts kept for a client, oldest first. */
208	    @Transactional(readOnly = true)
209	    public List<ClientContactView> contactsFor(Long clientId) {
210	        return contacts.findByClientIdOrderByIdAsc(clientId).stream()
211	                .map(c -> new ClientContactView(c.getId(), c.getClientId(), c.getName(),
212	                        c.getEmail(), c.getRole(), c.isPrimary()))
213	                .toList();
214	    }
215	
216	    /**
217	     * Pick a client's one main (primary) contact. Clears the flag across the client's contacts and
218	     * sets it on the chosen one, so exactly one is primary at a time. Returns the client's contacts.
219	     */
220	    @Transactional
221	    public List<ClientContactView> setPrimaryContact(Long clientId, Long contactId) {
222	        if (clientId == null || contactId == null) {
223	            throw new IllegalArgumentException("A client and contact are required");
224	        }
225	        jdbc.update("UPDATE contacts SET is_primary = FALSE WHERE client_id = ?", clientId);
226	        jdbc.update("UPDATE contacts SET is_primary = TRUE WHERE id = ? AND client_id = ?",
227	                contactId, clientId);
228	        return contactsFor(clientId);
229	    }
